"""Make a local scientific case viewer from archived real panoramas and exact traces."""
from pathlib import Path
import gzip,json,subprocess,hashlib,os
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'stage02_same_room/abc/cases'; REPO=ROOT.parent/'repo'; ENV={**os.environ,'GIT_NO_LAZY_FETCH':'1'}
pools=json.load(gzip.open(OUT/'PAIRED_CASE_INPUTS.json.gz','rt'))['images']; imgdir=OUT/'images'; imgdir.mkdir(exist_ok=True); receipt=[]
old_receipt=pd.read_csv(OUT/'ORIGINAL_PANORAMA_RECEIPT.csv').set_index('image').to_dict('index') if (OUT/'ORIGINAL_PANORAMA_RECEIPT.csv').exists() else {}
for pool in pools:
    path='data/mp3d_layout/valid/img/'+pool['meta']['image_id']+'.png'; name=pool['meta']['image']+'.png'
    if (imgdir/name).exists() and pool['meta']['image'] in old_receipt:
        b=(imgdir/name).read_bytes(); rec=old_receipt[pool['meta']['image']]; blob=rec['blob'];assert hashlib.sha256(b).hexdigest()==rec['sha256']
    else:
        if not REPO.exists():raise FileNotFoundError('Missing packaged case panorama images/'+name)
        blob=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD:'+path],env=ENV).decode().strip(); b=subprocess.check_output(['git','-C',str(REPO),'cat-file','blob',blob],env=ENV);(imgdir/name).write_bytes(b)
    assert b.startswith(b'\x89PNG\r\n\x1a\n');pool['image_relative_path']='images/'+name
    receipt.append(dict(image=pool['meta']['image'],image_id=pool['meta']['image_id'],historical_original_path=path,blob=blob,sha256=hashlib.sha256(b).hexdigest(),bytes=len(b)))
pd.DataFrame(receipt).to_csv(OUT/'ORIGINAL_PANORAMA_RECEIPT.csv',index=False)
def rows(p): return json.loads(pd.read_csv(p).to_json(orient='records',force_ascii=False))
events=rows(OUT.parent/'PAIRED_CASE_EVENTS.csv.gz'); states={}
for line in gzip.open(OUT/'PAIRED_CASE_CACHED_GEOMETRY_AND_TRACE.jsonl.gz','rt'):
    x=json.loads(line);selected=[g for g in x['full_state']['identity_groups'] if g['selected']];states[x['team_key']]={'geometry':x['geometry'],'selected_node_points':[p for g in selected for p in g['center']],'minimum_support':x['minimum_support'],'members':x['member_workers'],'diagnostics':x['full_state']['ring_diagnostics']}
data=dict(events=events,pools={x['pool_id']:x for x in pools},states=states,nodes=rows(OUT/'CASE_NODE_VOTE_LEDGER.csv.gz'),endpoints=rows(OUT/'CASE_ENDPOINT_MECHANISM_INDEX.csv'))
page=r'''<!doctype html><html lang="zh"><meta charset="utf-8"><title>v2.1 同房旧ABC案例</title>
<style>body{font:15px/1.6 system-ui,sans-serif;background:#f4f6f9;color:#15202b;margin:24px}main{max-width:1500px;margin:auto}h1{font-size:27px}h2{font-size:20px}.controls,.panel{background:white;border:1px solid #d4dce5;border-radius:8px;padding:16px;margin:16px 0}select{max-width:100%;font-size:14px;padding:7px}canvas{max-width:100%;height:auto;border:1px solid #ccd}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}td,th{border:1px solid #ddd;padding:4px 8px;text-align:left}th{background:#eef3f9}.muted{color:#526174}.pill{padding:4px 8px;border-radius:4px;background:#e6eef8}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.scroll{overflow-x:auto}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}@media(max-width:900px){.two{display:block}}a{color:#175699}</style>
<main><h1>同房旧 ABC，在 v2.1 当前标签下的完整案例</h1>
<p>14 个原事件、3 对图片、6 张原图；包括全部普通主向 14/7 事件，以及 10/5 中图对均值 C−B 跨视角反向的一对图片。这里保留原团队身份，未重新选队或运行融合。</p>
<p class="muted">A=D∪X，B=D∪Y，C=D∪Z。冻结 MV50 为 ≥50%。表中 D/替换块的局部支持是同一端点内的真实票数，不能由人数直接推出。节点编号只在当前端点内有效。原答顺序及融合环的确认状态沿用来源；原图可以帮助人工判断它们是否对应真实墙角。</p>
<div class="controls"><label>原事件 <select id="event"></select></label><br><label>视角 <select id="view"><option value="a">a</option><option value="b">b</option></select></label> <label>端点 <select id="arm"><option>A</option><option>B</option><option selected>C</option></select></label> <label>原答 <select id="raw"><option value="none">不叠加</option><option value="D">共同背景 D</option><option value="X">X</option><option value="Y">Y</option><option value="Z">Z</option><option value="team">本队全部成员</option><option value="all">本图全部合法原答</option></select></label></div>
<div class="panel"><h2 id="title"></h2><div id="meta"></div><p>白色实线：当前正式参考；青色细线：所选完整原答。橙色只在 complete_conditional 状态画完整共识环；其它状态仅画真实已选角点及底面散点，不闭合、不连边，不把候选图形显示成完整共识。参考及原答环保留。</p><p>所有有效环保留原顺序，按每角底部距离重建三维坐标，在相邻三维直边上采样后投影到全景图；跨接缝分段，不以二维像素直线代替顶/底边。原标注 1024×512 按比例映射到原图。</p><canvas id="pano" width="1536" height="768"></canvas><div class="two"><div><h3>底面形状或已选节点（冻结归一化坐标）</h3><canvas id="bev" width="700" height="500"></canvas></div><div><h3>成员与状态</h3><pre id="members"></pre><p id="q"></p><a id="original" target="_blank">打开原始完整图片</a></div></div></div>
<div class="panel"><h2>所有候选节点与局部票账</h2><p class="muted">包含未入选节点。达到全队门槛的替换块支持，仍不等同于另行融合该块得到相同结构。位置子簇是来源诊断；本轮不通过子簇数推定互斥语义。</p><div class="scroll"><table id="votes"></table></div></div>
<div class="panel"><h2>连接诊断原记录</h2><p class="muted">冻结环连接选择“支持最多的完整投影原答环”；下面的边支持是诊断量，并没有另加逐边 MV50 判定。节点已过票不等于完整连接已经成立。</p><pre id="ring"></pre></div>
<div class="panel"><h2>完整数据索引</h2><p><a href="PAIRED_CASE_INPUTS.json.gz">六图所有完整原答与当前参考</a> · <a href="PAIRED_CASE_CACHED_GEOMETRY_AND_TRACE.jsonl.gz">84 端点完整几何、候选节点、指派与环轨迹</a> · <a href="CASE_NODE_VOTE_LEDGER.csv.gz">局部票账</a> · <a href="CASE_RING_SUPPORT_DIAGNOSTICS.csv.gz">完整环与边支持</a> · <a href="CASE_RAW_GEOMETRY_IDENTITY_CHECK.csv.gz">4,959 项原始点一致检查</a> · <a href="CACHED_GEOMETRY_RECEIPT.csv">精确来源路径、行号与哈希</a></p><p>请在浏览器中打开本 HTML；图片及数据文件与它同目录解压即可。本页无联网脚本。人工重点：S9h-12 的低票候选是否代表相同墙角、底面凹角的漏选位置；S9h-10/19 与 pa4-42/44 在结构不变时，位置/高度差是否对应可见边界。</p></div></main>
<script id="data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id), colors={D:'#18bac8',X:'#87d6ec',Y:'#9365de',Z:'#26c7a0'};const eventSel=$('event'); d.events.forEach((e,i)=>{let o=document.createElement('option');o.value=i;o.textContent=`${e.image_a} / ${e.image_b} · ${e.n}/${e.m} · ${e.event_id}`;eventSel.appendChild(o)});
function fmt(x){return x===null||x===undefined?'不可评':Number(x).toFixed(3)}
function closed(ctx,p,color,scale,offset){if(!p||!p.length)return;ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.beginPath();p.concat([p[0]]).forEach((q,i)=>{const x=q[0]*scale+offset[0],y=q[1]*scale+offset[1];i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
// Same geometry as scripts/half_case_viewer.js: floor y=-1; each top
// corner uses its own paired bottom radius, then original ring adjacency.
function world(p,bottom=null){const az=p[0]/1024*2*Math.PI,el=(.5-p[1]/512)*Math.PI;const r=bottom?-1/Math.tan((.5-bottom[1]/512)*Math.PI):-1/Math.tan(el);return [-Math.sin(az)*r,bottom?r*Math.tan(el):-1,Math.cos(az)*r]}
function project(v){let x=Math.atan2(-v[0],v[2])/(2*Math.PI);if(x<0)x+=1;return [x*1024,(.5-Math.atan2(v[1],Math.hypot(v[0],v[2]))/Math.PI)*512]}
function fusionDisplay(ep,s){const complete=ep.score_status==='complete_conditional';const pts=complete?(s.geometry.points||[]):(s.selected_node_points||[]);const floor=complete?(s.geometry.footprint||[]):pts.filter((_,i)=>i%2===1).map(p=>world(p)).filter(p=>p.every(Number.isFinite)).map(p=>[p[0],p[2]]);return {complete,points:pts,floor,mode:complete?'complete_ring':'selected_points_only'}}
function panoMarkers(ctx,pts,color){ctx.save();ctx.fillStyle=color;ctx.globalAlpha=.98;for(const q of pts){ctx.beginPath();ctx.arc(q[0]*1.5,q[1]*1.5,5,0,Math.PI*2);ctx.fill()}ctx.restore()}
function bevMarkers(ctx,pts,color,scale,offset){ctx.save();ctx.fillStyle=color;for(const q of pts){ctx.beginPath();ctx.arc(q[0]*scale+offset[0],q[1]*scale+offset[1],5,0,Math.PI*2);ctx.fill()}ctx.restore()}
function poly(ctx,pts,color,alpha,width){if(!pts||pts.length<2)return;ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=width;ctx.globalAlpha=alpha;const pairs=[];for(let i=0;i+1<pts.length;i+=2)pairs.push([pts[i],pts[i+1]]);ctx.beginPath();for(const q of pairs){ctx.moveTo(q[0][0]*1.5,q[0][1]*1.5);ctx.lineTo(q[1][0]*1.5,q[1][1]*1.5)}ctx.stroke();for(let i=0;i<pairs.length;i++)for(const which of [0,1]){const j=(i+1)%pairs.length,a=world(pairs[i][which],which===0?pairs[i][1]:null),b=world(pairs[j][which],which===0?pairs[j][1]:null);if(!a.concat(b).every(Number.isFinite))continue;let last=null;ctx.beginPath();for(let k=0;k<=48;k++){const t=k/48,p=project(a.map((x,z)=>x+(b[z]-x)*t));if(last&&Math.abs(p[0]-last[0])<512)ctx.lineTo(p[0]*1.5,p[1]*1.5);else ctx.moveTo(p[0]*1.5,p[1]*1.5);last=p}ctx.stroke()}for(const q of pts){ctx.beginPath();ctx.arc(q[0]*1.5,q[1]*1.5,3,0,Math.PI*2);ctx.fill()}ctx.restore()}
let token=0;function render(){let serial=++token,e=d.events[Number(eventSel.value)],v=$('view').value,a=$('arm').value,k=e[`team_${a}_${v}`],p=d.pools[e[`pool_id_${v}`]],s=d.states[k],ep=d.endpoints.find(x=>x.event_id===e.event_id&&x.view===v&&x.arm===a),votes=d.nodes.filter(x=>x.event_id===e.event_id&&x.view===v&&x.arm===a),display=fusionDisplay(ep,s);$('title').textContent=`${p.meta.image} · ${a} · ${e.n}人换${e.m}人`; $('meta').textContent=`当前参考 ${p.meta.reference_id}；难度 ${p.meta.difficulty}；MV50 最小支持 ${s.minimum_support}。${display.complete?'完整输出：显示冻结融合环。':'非完整输出：仅显示已选角点，不闭合、不连边。'}`;let image=new Image();image.onload=()=>{if(serial!==token)return;let c=$('pano').getContext('2d');c.clearRect(0,0,1536,768);c.drawImage(image,0,0,1536,768);let raw=$('raw').value,ws=raw==='team'?s.members:raw==='all'?p.records.map(x=>x.worker):raw==='none'?[]:e[raw+'_members'].split('|');p.records.filter(x=>ws.includes(x.worker)).forEach(x=>poly(c,x.points,'#10d5f5',.35,1));poly(c,p.reference.points_1024x512,'white',.98,2.4);if(display.complete)poly(c,display.points,'#ff9f1c',.98,3);else panoMarkers(c,display.points,'#ff9f1c');};image.src=p.image_relative_path;$('original').href=p.image_relative_path;$('members').textContent=['D','X','Y','Z'].map(b=>`${b}: ${e[b+'_members']}`).join('\n')+`\n\n本队：${s.members.join(', ')}\n评分状态：${ep.score_status}\n候选节点 ${ep.candidate_nodes}；入选 ${ep.selected_nodes}\n显示模式：${display.complete?'完整输出环':'仅已选节点；无闭环或连接'}\n环顺序状态：${s.geometry.order_status||s.geometry.status}`;$('q').textContent=`B8L2=${fmt(ep.B8L2)}；D10=${fmt(ep.D10)}。缺值保留不可评，不填 0。`;
let bc=$('bev').getContext('2d');bc.clearRect(0,0,700,500);bc.fillStyle='#23313e';bc.fillRect(0,0,700,500);let all=[...(p.reference.floor_xz_h||[]),...display.floor];if(all.length){let xs=all.map(q=>q[0]),ys=all.map(q=>q[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),sc=Math.min(620/Math.max(xmax-xmin,.01),420/Math.max(ymax-ymin,.01)),off=[40-xmin*sc,40-ymin*sc];closed(bc,p.reference.floor_xz_h,'white',sc,off);if(display.complete)closed(bc,display.floor,'#ff9f1c',sc,off);else bevMarkers(bc,display.floor,'#ff9f1c',sc,off)};
$('votes').innerHTML='<tr><th>端点内节点</th><th>入选</th><th>总票</th><th>D票</th><th>替换块票</th><th>D达到全队门槛</th><th>块达到门槛</th><th>底/顶位置子簇</th><th>块成员</th></tr>'+votes.map(n=>`<tr><td>${n.feature_id}</td><td>${n.selected?'是':'否'}</td><td>${n.support}</td><td>${n.D_support}</td><td>${n.block_support}</td><td>${n.D_reaches_team_MV50?'是':'否'}</td><td>${n.block_reaches_team_MV50?'是':'否'}</td><td>${n.bottom_location_clusters}/${n.top_location_clusters}</td><td>${n.block_workers}</td></tr>`).join('');$('ring').textContent=JSON.stringify(s.diagnostics,null,2)};for(let id of ['event','view','arm','raw'])$(id).addEventListener('change',render);render();</script></html>'''
js=json.dumps(data,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('</','<\\/')
(OUT/'CASE_VIEWER.html').write_text(page.replace('__DATA__',js),encoding='utf8')
